<?php

declare(strict_types=1);namespace backend\controllers;use backend\components\AdminController;use common\models\{SupportTicket,SupportMessage,SupportAttachment};use frontend\models\ReplyForm;use Yii;use yii\data\ActiveDataProvider;use yii\web\NotFoundHttpException;
final class SupportController extends AdminController { protected string $permission='manageSupport'; public function actionIndex():string{return $this->render('index',['dataProvider'=>new ActiveDataProvider(['query'=>SupportTicket::find()->orderBy(['updated_at'=>SORT_DESC])])]);}public function actionAttachment(int $id){$a=SupportAttachment::findOne($id);if(!$a)throw new NotFoundHttpException();$path=Yii::getAlias('@storage/uploads/support/'.$a->stored_name);if(!is_file($path))throw new NotFoundHttpException();return Yii::$app->response->sendFile($path,$a->original_name,['mimeType'=>$a->mime_type,'inline'=>false]);}public function actionView(int $id){$t=SupportTicket::findOne($id);if(!$t)throw new NotFoundHttpException();$m=new ReplyForm();if($m->load(Yii::$app->request->post())&&$m->validate()){$msg=new SupportMessage(['ticket_id'=>$t->id,'user_id'=>Yii::$app->user->id,'body'=>$m->message,'is_staff'=>1,'created_at'=>date('Y-m-d H:i:s')]);$msg->save(false);$t->status=SupportTicket::STATUS_ANSWERED;$t->assigned_to=Yii::$app->user->id;$t->updated_at=date('Y-m-d H:i:s');$t->save(false);if($t->user)Yii::$app->mailer->compose('support-reply',['ticket'=>$t,'message'=>$msg])->setTo($t->user->email)->setSubject('Ответ поддержки HiveTech #'.$t->id)->send();return $this->refresh();}return $this->render('view',['ticket'=>$t,'model'=>$m]);}public function actionClose(int $id){if(Yii::$app->request->isPost){$t=SupportTicket::findOne($id);if($t){$t->status=SupportTicket::STATUS_CLOSED;$t->updated_at=date('Y-m-d H:i:s');$t->save(false);}}return $this->redirect(['view','id'=>$id]);}}
